const raw = $input.first().json.stdout || "";
const parts = raw.split("===FILES===");
const secretsRaw = (parts[0] || "").replace("===SECRETS===", "").trim();
let secrets = {};
try { secrets = JSON.parse(secretsRaw); } catch (e) {}
const lines = (parts[1] || "").split("\n").map(s => s.trim()).filter(Boolean);
const chatMap = { "Юрий": "599756870", "Екатерина": "599756870", "Николай": "599756870", "Владимир": "599756870", "Виталий": "599756870", "Константин": "599756870", "Мария": "599756870", "Ольга": "599756870" };
const out = [];
for (const line of lines) {
  const f = line.split("\t");
  if (f.length < 2) continue;
  const manager = f[0] || "Неизвестно";
  const p = f[1];
  const base = p.split("/").pop();
  const label = f[2] || base;
  const ext = (base.split(".").pop() || "").toLowerCase();
  if (ext === "zip") continue;
  if (["pdf","docx","doc","xlsx","xls","txt"].includes(ext)) {
    out.push({ json: {
      path: p, filename: label, manager,
      chat_id: chatMap[manager] || "599756870",
      max_token: secrets.max_token || "",
      kimi_key: secrets.kimi_api_key || ""
    }});
  }
}
return out;

const metaAll = $('Разложить по файлам').all();
const prompt = "Ты — тендерный аналитик компании АЛТЭК (оптовая торговля металлопрокатом, Екатеринбург). Проанализируй тендерный документ и выдай краткую карточку строго по шаблону:\n\n📋 Предмет закупки: ...\n🏢 Заказчик: ...\n💰 НМЦК / бюджет: ...\n⏰ Дедлайн подачи заявок: ...\n📍 Площадка / регион: ...\n⚠️ Ключевые требования и риски (3–5 пунктов)\n💡 Рекомендация: участвовать / не участвовать и почему (1–2 предложения)\n\nПравила: если данных нет в документе — пиши «не указано»; ответ не длиннее 2500 символов; без заголовков markdown, только структура выше.";
return $input.all().map((item, i) => {
  const meta = (metaAll[i] || metaAll[0]).json;
  let content = item.json;
  if (typeof content !== "string") {
    content = (content && (content.content || content.text)) || JSON.stringify(content);
  }
  const MAXLEN = 60000;
  if (content.length > MAXLEN) content = content.slice(0, MAXLEN) + "\n\n[текст документа обрезан]";
  const body = {
    model: "kimi-k3.1-pro",
    temperature: 1,
    max_tokens: 16000,
    messages: [
      { role: "system", content: "Содержимое тендерного документа «" + meta.filename + "»:\n\n" + content },
      { role: "user", content: prompt }
    ]
  };
  return { json: { kimi_key: meta.kimi_key, body: body } };
});

const metaAll = $('Разложить по файлам').all();
return $input.all().map((item, i) => {
  const meta = (metaAll[i] || metaAll[0]).json;
  const resp = item.json;
  let text = "";
  try { text = (resp.choices[0].message.content || "").trim(); } catch (e) { text = ""; }
  if (!text) {
    try {
      const r = resp.choices[0].message.reasoning_content || "";
      const j = r.lastIndexOf("📋");
      if (j >= 0) text = r.slice(j).trim();
    } catch (e) {}
  }
  if (!text) text = "⚠️ Не удалось получить разбор от Kimi: " + JSON.stringify(resp).slice(0, 400);
  const msg = "📄 Разбор документа: " + meta.filename + "\n(папка: " + meta.manager + ")\n\n" + text;
  return { json: { chat_id: meta.chat_id, max_token: meta.max_token, text: msg } };
});
